/** SymPy's doctests and unit tests of this module with SymPy's printed results. Generated by compat/totests from the SymPy corpora; do not edit. */

import { describe, expect, it } from 'vitest';
import { Add, Dummy, Mul, Pow, Sym, add, andrePoly, bernoulliCPoly, bernoulliPoly, dummyEq, eulerPoly, factor, genocchiPoly, mul, pow, rational } from '../../src';
import { sympyStr } from '../sympy-str';

describe("doctests of sympy.polys.appellseqs", () => {
  it("andre_poly(9, x)", () => {
    const x = new Sym('x');
    expect(sympyStr(andrePoly(rational(9), x))).toBe('x**9 - 36*x**7 + 630*x**5 - 5124*x**3 + 12465*x');
  });
  it("bernoulli_poly(5, x)", () => {
    const x = new Sym('x');
    expect(sympyStr(bernoulliPoly(rational(5), x))).toBe('x**5 - 5*x**4/2 + 5*x**3/3 - x/6');
  });
  // the arguments do not type-check against the public API
  //   summation(x**4, (x, -6, 27))
  //   => 3144337
  it.todo("summation(x**4, (x, -6, 27))");
  it("psum(1, 1, x).factor()", () => {
    const x = new Sym('x');
    expect(sympyStr(factor(add(rational(-1, 2), mul(rational(1, 2), pow(add(1, x), 2)), mul(rational(-1, 2), x))))).toBe('x*(x + 1)/2');
  });
  it("psum(2, 1, x).factor()", () => {
    const x = new Sym('x');
    expect(sympyStr(factor(add(rational(1, 6), mul(rational(-1, 2), pow(add(1, x), 2)), mul(rational(1, 3), pow(add(1, x), 3)), mul(rational(1, 6), x))))).toBe('x*(x + 1)*(2*x + 1)/6');
  });
  it("psum(3, 1, x).factor()", () => {
    const x = new Sym('x');
    expect(sympyStr(factor(add(mul(rational(-1, 2), pow(add(1, x), 3)), mul(rational(1, 4), pow(add(1, x), 2)), mul(rational(1, 4), pow(add(1, x), 4)))))).toBe('x**2*(x + 1)**2/4');
  });
});

